const item = $input.first();
const hdrs = item.json.headers || {};
const pendingMediaId = hdrs['idempotency-key'] || hdrs['Idempotency-Key'] || require('crypto').randomUUID();
const gateway = String($env.MEDIA_GATEWAY_URL || 'http://host.docker.internal:3081').replace(/\/$/, '');
const secret = $env.MEDIA_GATEWAY_SECRET || $env.N8N_CAPTURE_WEBHOOK_SECRET;

const binary = item.binary || {};
const binKey = Object.keys(binary)[0];
if (!binKey) {
  throw new Error('No binary in webhook. Prefer PWA → media-gateway /upload directly.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
const filename = binary[binKey].fileName || 'upload.bin';
const mimeType = binary[binKey].mimeType || 'application/octet-stream';

const parsed = await this.helpers.httpRequest({
  method: 'POST',
  url: `${gateway}/upload`,
  headers: {
    'X-Webhook-Secret': secret,
    'Idempotency-Key': pendingMediaId,
  },
  formData: {
    file: {
      value: buffer,
      options: { filename, contentType: mimeType },
    },
    metadata: JSON.stringify({ filename, mimeType, pendingMediaId }),
  },
  json: true,
});

return [{
  json: {
    mediaId: parsed.mediaId || pendingMediaId,
    fileId: parsed.fileId,
    status: parsed.status || 'created',
    uploadComplete: true,
    pendingMediaId,
    filename,
    receivedAt: parsed.receivedAt || new Date().toISOString(),
  },
}];
